import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force HIP compilation
os.environ.setdefault("CXX", "hipcc")

# Simple, bandwidth-bound kernel; using vectorized loads when possible.
# We only need out = in * factor (since original residual path is identical):
#   out = x*scaling_factor + x = x*(1+scaling_factor)
# This removes the clone+detach and the add kernel.

scale_cpp = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

template <int VEC>
__global__ void scale_kernel(const float* __restrict__ inp, float* __restrict__ out, float factor, int n) {
    int tid = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int idx = tid * VEC;
    if (idx >= n) return;

    #pragma unroll
    for (int i = 0; i < VEC; i++) {
        int j = idx + i;
        if (j < n) out[j] = inp[j] * factor;
    }
}

torch::Tensor scale_fp32(torch::Tensor x, double factor_d) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto out = torch::empty_like(x);

    const int n = (int)x.numel();
    const float factor = (float)factor_d;

    // Choose vector width if aligned.
    uintptr_t addr_in = (uintptr_t)x.data_ptr<float>();
    uintptr_t addr_out = (uintptr_t)out.data_ptr<float>();
    bool aligned16 = ((addr_in | addr_out) & 0xF) == 0;

    const int threads = 256;
    if (aligned16) {
        const int VEC = 4;
        int blocks = (n + (threads * VEC - 1)) / (threads * VEC);
        hipLaunchKernelGGL((scale_kernel<VEC>), dim3(blocks), dim3(threads), 0, 0,
                           (const float*)x.data_ptr<float>(), (float*)out.data_ptr<float>(), factor, n);
    } else {
        const int VEC = 1;
        int blocks = (n + (threads * VEC - 1)) / (threads * VEC);
        hipLaunchKernelGGL((scale_kernel<VEC>), dim3(blocks), dim3(threads), 0, 0,
                           (const float*)x.data_ptr<float>(), (float*)out.data_ptr<float>(), factor, n);
    }

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("scale_fp32", &scale_fp32, "Scale fp32 tensor (HIP)");
}
"""

scale_ext = load_inline(
    name="scale_ext_fp32",
    cpp_sources=scale_cpp,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, scaling_factor):
        super().__init__()
        self.matmul = nn.Linear(in_features, out_features)
        # Precompute fused factor: x*(scale) + x == x*(1+scale)
        self.register_buffer("_fused_factor", torch.tensor(1.0 + float(scaling_factor), dtype=torch.float32))

    def forward(self, x):
        y = self.matmul(x)
        # Use custom HIP kernel for scaling
        return scale_ext.scale_fp32(y, float(self._fused_factor.item()))


def get_inputs():
    batch_size = 16384
    in_features = 4096
    return [torch.rand(batch_size, in_features, device="cuda", dtype=torch.float32)]


def get_init_inputs():
    in_features = 4096
    out_features = 4096
    scaling_factor = 0.5
    return [in_features, out_features, scaling_factor]

import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Ensure HIP compilation
os.environ.setdefault("CXX", "hipcc")

# Fused kernel: maxpool1d(kernel=2,stride=2) over last dim, then sum over pooled dim, then scale
# Input: [B, N] float32 contiguous. Output: [B] float32.
cpp_source = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__global__ void maxpool2_sum_scale_kernel(const float* __restrict__ x, float* __restrict__ out,
                                         int64_t B, int64_t N, float scale) {
    // N must be even for kernel_size=2 stride=2 pooling
    int b = (int)blockIdx.x;
    if (b >= B) return;

    // Each block reduces one row.
    float acc = 0.0f;
    int64_t pairs = N >> 1;
    const float* row = x + (int64_t)b * N;

    // Strided loop over pooled indices
    for (int64_t i = (int64_t)threadIdx.x; i < pairs; i += (int64_t)blockDim.x) {
        int64_t j = i << 1;
        float a = row[j];
        float c = row[j + 1];
        acc += (a > c ? a : c);
    }

    // Block reduction
    __shared__ float smem[256];
    smem[threadIdx.x] = acc;
    __syncthreads();

    for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
        if (threadIdx.x < offset) {
            smem[threadIdx.x] += smem[threadIdx.x + offset];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        out[b] = smem[0] * scale;
    }
}

torch::Tensor maxpool2_sum_scale_hip(torch::Tensor x, double scale_factor) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B,N]");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    auto B = x.size(0);
    auto N = x.size(1);
    TORCH_CHECK((N % 2) == 0, "N must be even for kernel_size=2 pooling");

    auto out = torch::empty({B}, torch::TensorOptions().dtype(x.dtype()).device(x.device()));

    const int threads = 256;
    dim3 blocks((unsigned)B);
    auto stream = at::cuda::getDefaultCUDAStream();

    hipLaunchKernelGGL(maxpool2_sum_scale_kernel, blocks, dim3(threads), 0, stream,
                      (const float*)x.data_ptr<float>(), (float*)out.data_ptr<float>(),
                      (int64_t)B, (int64_t)N, (float)scale_factor);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("maxpool2_sum_scale_hip", &maxpool2_sum_scale_hip, "Fused maxpool2+sum+scale (HIP)");
}
'''

ext = load_inline(
    name="fused_pool_sum_scale_ext",
    cpp_sources=cpp_source,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized Model: keep rocBLAS GEMM for Linear, fuse post-ops (maxpool+sum+scale) into one HIP kernel."""

    def __init__(self, in_features, out_features, kernel_size, scale_factor):
        super().__init__()
        assert kernel_size == 2, "This optimized kernel assumes kernel_size=2"
        self.matmul = nn.Linear(in_features, out_features)
        self.scale_factor = float(scale_factor)

    def forward(self, x):
        x = self.matmul(x)
        # x: [B, out_features]
        return ext.maxpool2_sum_scale_hip(x, self.scale_factor)


