import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force hipcc for ROCm
os.environ.setdefault("CXX", "hipcc")

src = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

__device__ __forceinline__ float my_tanh(float x) {
    // tanhf is available; use fast approx if desired
    return tanhf(x);
}

// Fused: (tanh(x - sub1) - sub2) then AvgPool2d(k=2, stride=2)
__global__ void fused_postpool2_kernel(
    const float* __restrict__ inp,
    float* __restrict__ out,
    int N, int C, int H, int W,
    float sub1, float sub2)
{
    // Output dims
    int Ho = H >> 1;
    int Wo = W >> 1;
    int idx = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int total = N * C * Ho * Wo;
    if (idx >= total) return;

    int wo = idx % Wo;
    int t = idx / Wo;
    int ho = t % Ho;
    t /= Ho;
    int c = t % C;
    int n = t / C;

    int h0 = ho << 1;
    int w0 = wo << 1;

    // base index in NCHW
    int base = ((n * C + c) * H + h0) * W + w0;

    float v00 = inp[base];
    float v01 = inp[base + 1];
    float v10 = inp[base + W];
    float v11 = inp[base + W + 1];

    v00 = my_tanh(v00 - sub1) - sub2;
    v01 = my_tanh(v01 - sub1) - sub2;
    v10 = my_tanh(v10 - sub1) - sub2;
    v11 = my_tanh(v11 - sub1) - sub2;

    out[idx] = 0.25f * (v00 + v01 + v10 + v11);
}

torch::Tensor fused_postpool2_hip(torch::Tensor x, double sub1, double sub2) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous NCHW");
    TORCH_CHECK(x.dim() == 4, "x must be NCHW");

    auto N = (int)x.size(0);
    auto C = (int)x.size(1);
    auto H = (int)x.size(2);
    auto W = (int)x.size(3);
    TORCH_CHECK((H % 2) == 0 && (W % 2) == 0, "H and W must be even for k=2, s=2 pool");

    int Ho = H / 2;
    int Wo = W / 2;

    auto out = torch::empty({N, C, Ho, Wo}, x.options());

    int total = N * C * Ho * Wo;
    constexpr int threads = 256;
    int blocks = (total + threads - 1) / threads;

    hipLaunchKernelGGL(
        fused_postpool2_kernel,
        dim3(blocks), dim3(threads),
        0, at::cuda::getDefaultCUDAStream(),
        (const float*)x.data_ptr<float>(),
        (float*)out.data_ptr<float>(),
        N, C, H, W,
        (float)sub1, (float)sub2);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_postpool2_hip", &fused_postpool2_hip, "fused tanh/sub/sub + avgpool2d(k=2,s=2) (HIP)");
}
'''

fused_ext = load_inline(
    name="fused_postpool2_ext",
    cpp_sources=src,
    functions=None,
    with_cuda=True,
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized model: keep Conv2d (MIOpen) and fuse subtract/tanh/subtract/avgpool into one HIP kernel."""

    def __init__(self, in_channels, out_channels, kernel_size, subtract1_value, subtract2_value, kernel_size_pool):
        super().__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        assert kernel_size_pool == 2, "This optimized kernel assumes AvgPool2d kernel_size=2 (stride=2)."
        self.subtract1_value = float(subtract1_value)
        self.subtract2_value = float(subtract2_value)

    def forward(self, x):
        x = self.conv(x)
        # Ensure contiguous for the fused kernel
        if not x.is_contiguous():
            x = x.contiguous()
        return fused_ext.fused_postpool2_hip(x, self.subtract1_value, self.subtract2_value)


