import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force HIP compilation on ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused: AvgPool1d(kernel=16,stride=16) over feature dim + GELU + scale + max-reduction
# Input: (B, 8192) float32 contiguous
# Output: (B,) float32

hip_src = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>

__device__ __forceinline__ float gelu_tanh(float x) {
    // tanh approximation used by PyTorch GELU
    const float k0 = 0.7978845608028654f; // sqrt(2/pi)
    const float k1 = 0.044715f;
    float x3 = x * x * x;
    float u = k0 * (x + k1 * x3);
    float t = tanhf(u);
    return 0.5f * x * (1.0f + t);
}

template<int K>
__global__ void fused_pool_gelu_scale_max_kernel(const float* __restrict__ inp, float* __restrict__ out,
                                                 int B, int N, float scale) {
    // one block per batch element
    int b = blockIdx.x;
    if (b >= B) return;

    // N assumed multiple of K
    int S = N / K; // pooled length

    float local_max = -INFINITY;
    const float* base = inp + ((size_t)b) * N;

    for (int s = threadIdx.x; s < S; s += blockDim.x) {
        int offset = s * K;
        float sum = 0.0f;
        #pragma unroll
        for (int i = 0; i < K; i++) {
            sum += base[offset + i];
        }
        float avg = sum * (1.0f / (float)K);
        float y = gelu_tanh(avg) * scale;
        local_max = fmaxf(local_max, y);
    }

    __shared__ float shmem[256];
    int tid = threadIdx.x;
    shmem[tid] = local_max;
    __syncthreads();

    // reduction
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) {
            shmem[tid] = fmaxf(shmem[tid], shmem[tid + stride]);
        }
        __syncthreads();
    }

    if (tid == 0) out[b] = shmem[0];
}

torch::Tensor fused_pool_gelu_scale_max(torch::Tensor x, double scale_factor) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D (B, N)");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    int64_t B64 = x.size(0);
    int64_t N64 = x.size(1);
    TORCH_CHECK(N64 % 16 == 0, "feature dim must be multiple of 16");

    int B = (int)B64;
    int N = (int)N64;

    auto out = torch::empty({B64}, x.options());

    const int threads = 256;
    dim3 blocks(B);
    hipLaunchKernelGGL((fused_pool_gelu_scale_max_kernel<16>), blocks, dim3(threads), 0, 0,
                       (const float*)x.data_ptr<float>(), (float*)out.data_ptr<float>(), B, N, (float)scale_factor);

    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_pool_gelu_scale_max", &fused_pool_gelu_scale_max, "fused avgpool+gelu+scale+max (HIP)");
}
'''

ext = load_inline(
    name="fused_pool_gelu_scale_max_ext",
    cpp_sources="",
    cuda_sources=hip_src,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized model: keep GEMM (nn.Linear) and fuse AvgPool+GELU+Scale+Max."""

    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super().__init__()
        assert pool_kernel_size == 16, "This optimized kernel assumes kernel_size=16"
        self.matmul = nn.Linear(in_features, out_features)
        self.scale_factor = float(scale_factor)

    def forward(self, x):
        x = self.matmul(x)
        # x: (B, 8192)
        return ext.fused_pool_gelu_scale_max(x, self.scale_factor)


