import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Force HIP compilation
os.environ.setdefault("CXX", "hipcc")

# Fused: tanh -> scale -> bias add -> maxpool (stride=kernel)
# Input/Output are NCHW FP32 contiguous.

hip_src = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__device__ __forceinline__ float fast_tanh(float x) {
    // Use hardware tanh
    return __tanhf(x);
}

template<int POOL_K>
__global__ void fused_tanh_scale_bias_maxpool_kernel(
    const float* __restrict__ x,  // [N, C, H, W]
    const float* __restrict__ bias, // [C] (broadcast)
    float* __restrict__ out,       // [N, C, OH, OW]
    int N, int C, int H, int W,
    float scale,
    int OH, int OW)
{
    // Flattened index over N*C*OH*OW
    int idx = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int total = N * C * OH * OW;
    if (idx >= total) return;

    int ow = idx % OW;
    int t = idx / OW;
    int oh = t % OH;
    t /= OH;
    int c = t % C;
    int n = t / C;

    int base_h = oh * POOL_K;
    int base_w = ow * POOL_K;

    // Pointers
    const int HW = H * W;
    const float* x_nc = x + (n * C + c) * HW;

    float b = bias[c];

    float m = -INFINITY;

    #pragma unroll
    for (int ph = 0; ph < POOL_K; ++ph) {
        int ih = base_h + ph;
        const float* row = x_nc + ih * W + base_w;
        #pragma unroll
        for (int pw = 0; pw < POOL_K; ++pw) {
            float v = row[pw];
            v = fast_tanh(v);
            v = v * scale + b;
            m = v > m ? v : m;
        }
    }

    out[idx] = m;
}

torch::Tensor fused_tanh_scale_bias_maxpool_hip(torch::Tensor x, torch::Tensor bias, double scale, int64_t pool_k) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == at::ScalarType::Float, "x must be float32");
    TORCH_CHECK(bias.scalar_type() == at::ScalarType::Float, "bias must be float32");

    x = x.contiguous();
    // bias is [C,1,1] in model; flatten to [C]
