# Fused: (x/divisor) -> GELU (exact erf variant)
# We keep nn.Linear (GEMM+bias) as-is (rocBLAS), and fuse divide+gelu into one kernel.

cpp_source = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

#ifndef __HIP_PLATFORM_AMD__
#define __HIP_PLATFORM_AMD__
#endif

__device__ __forceinline__ float gelu_erf(float x) {
    // exact GELU: 0.5*x*(1+erf(x/sqrt(2)))
    const float inv_sqrt2 = 0.7071067811865475244f;
    return 0.5f * x * (1.0f + erff(x * inv_sqrt2));
}

__global__ void div_gelu_kernel(const float* __restrict__ inp, float* __restrict__ out, int64_t n, float inv_div) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;

    // Vectorize when possible (float4)
    int64_t n4 = n / 4;
    const float4* in4 = reinterpret_cast<const float4*>(inp);
    float4* out4 = reinterpret_cast<float4*>(out);

    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = in4[i];
        float x0 = v.x * inv_div;
        float x1 = v.y * inv_div;
        float x2 = v.z * inv_div;
        float x3 = v.w * inv_div;
        v.x = gelu_erf(x0);
        v.y = gelu_erf(x1);
        v.z = gelu_erf(x2);
        v.w = gelu_erf(x3);
        out4[i] = v;
    }

    // tail
    int64_t base = n4 * 4;
    for (int64_t j = base + idx; j < n; j += stride) {
        float x = inp[j] * inv_div;
        out[j] = gelu_erf(x);
    }
}

