    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    auto out = torch::empty_like(x);
    int64_t n = x.numel();
    float inv_div = 1.0f / (float)divisor;

    const int threads = 256;
    int blocks = (int)((n + threads - 1) / threads);
    // cap blocks to avoid excessive launch
    if (blocks > 4096) blocks = 4096;

    hipStream_t stream = (hipStream_t)at::cuda::getDefaultCUDAStream();
    hipLaunchKernelGGL(div_gelu_kernel, dim3(blocks), dim3(threads), 0, stream,
                       (const float*)x.data_ptr<float>(), (float*)out.data_ptr<float>(), n, inv_div);
    return out;
}

