# Ensure we compile with HIPCC on ROCm
os.environ.setdefault("CXX", "hipcc")

# Fused Swish(x) = x * sigmoid(x) and scaling in a single HIP kernel.
# This removes the separate sigmoid + mul + mul kernels in the reference.

cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <hip/hip_runtime.h>

__device__ __forceinline__ float sigmoid_f(float x) {
    // Numerically-stable sigmoid
    // sigmoid(x) = 1 / (1 + exp(-x))
    return 1.0f / (1.0f + expf(-x));
}

__global__ void swish_scale_kernel(const float* __restrict__ x, float* __restrict__ y, int64_t n, float scale) {
    int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;

    // Vectorized path for better memory throughput when aligned
    // Handle in float4 chunks where possible.
    int64_t n4 = n / 4;
    const float4* x4 = reinterpret_cast<const float4*>(x);
    float4* y4 = reinterpret_cast<float4*>(y);

    for (int64_t i = tid; i < n4; i += stride) {
        float4 v = x4[i];
        float s0 = sigmoid_f(v.x);
        float s1 = sigmoid_f(v.y);
        float s2 = sigmoid_f(v.z);
        float s3 = sigmoid_f(v.w);
        float4 o;
        o.x = (v.x * s0) * scale;
        o.y = (v.y * s1) * scale;
        o.z = (v.z * s2) * scale;
        o.w = (v.w * s3) * scale;
        y4[i] = o;
    }

    // Remainder
    int64_t start = n4 * 4;
    for (int64_t i = start + tid; i < n; i += stride) {
        float v = x[i];
        float s = sigmoid_f(v);
        y[i] = (v * s) * scale;
    }
}

torch::Tensor swish_scale_hip(torch::Tensor x, double scale) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be FP32");
    auto x_contig = x.contiguous();
    auto y = torch::empty_like(x_contig);

    int64_t n = x_contig.numel();
    if (n == 0) return y;

    const int threads = 256;
    // Use enough blocks to cover the device, but avoid oversubscription
    int blocks = (int)((n + threads - 1) / threads);
    blocks = blocks > 4096 ? 4096 : blocks;

    hipStream_t stream = (hipStream_t)at::cuda::getDefaultCUDAStream();
    swish_scale_kernel<<<blocks, threads, 0, stream>>>(
        (const float*)x_contig.data_ptr<float>(),
        (float*)y.data_ptr<float>(),
        n,
        (float)scale
    );
    return y;
}

