hip_src = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>

// Fused: softmax over C (dim=1) then maxpool3d k=2,s=2 twice -> equivalent to pooling over a 4x4x4 region with stride 4.
// Input x: [B, C, D, H, W] (float32, contiguous)
// Output y: [B, C, D/4, H/4, W/4]

__device__ __forceinline__ float fast_exp(float x) {
    return __expf(x);
}

__global__ void softmax_pool4_kernel(const float* __restrict__ x, float* __restrict__ y,
                                    int B, int C, int D, int H, int W,
                                    int OD, int OH, int OW) {
    int idx = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int out_numel = B * C * OD * OH * OW;
    if (idx >= out_numel) return;

    int t = idx;
    int ow = t % OW; t /= OW;
    int oh = t % OH; t /= OH;
    int od = t % OD; t /= OD;
    int c  = t % C;  t /= C;
    int b  = t;

    int id0 = od * 4;
    int ih0 = oh * 4;
    int iw0 = ow * 4;

    float maxval = -INFINITY;

    // Iterate over 4x4x4 voxels; for each voxel compute softmax value for channel c, then take max.
    #pragma unroll
    for (int dz = 0; dz < 4; ++dz) {
        int id = id0 + dz;
        int base_d = ((b * C) * D + 0) * H * W + id * H * W;
        #pragma unroll
        for (int dy = 0; dy < 4; ++dy) {
            int ih = ih0 + dy;
            int base_dh = base_d + ih * W;
            #pragma unroll
            for (int dx = 0; dx < 4; ++dx) {
                int iw = iw0 + dx;

                // Find max across channels at this voxel
                float m = -INFINITY;
                int voxel_offset = base_dh + iw;
                // x layout: (((b*C + cc)*D + id)*H + ih)*W + iw
                // Our base_d computed for cc=0, so add cc*D*H*W
                #pragma unroll
                for (int cc = 0; cc < 16; ++cc) {
                    if (cc >= C) break;
                    float v = x[voxel_offset + cc * D * H * W];
                    m = v > m ? v : m;
                }

                // Sum exp across channels
                float s = 0.0f;
                #pragma unroll
                for (int cc = 0; cc < 16; ++cc) {
                    if (cc >= C) break;
                    float v = x[voxel_offset + cc * D * H * W];
                    s += fast_exp(v - m);
                }

                float vc = x[voxel_offset + c * D * H * W];
                float p = fast_exp(vc - m) / s;
                maxval = p > maxval ? p : maxval;
            }
        }
    }

    y[idx] = maxval;
}

torch::Tensor softmax_pool4_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK(x.dim() == 5, "x must be 5D NCDHW");

    int B = (int)x.size(0);
    int C = (int)x.size(1);
    int D = (int)x.size(2);
    int H = (int)x.size(3);
    int W = (int)x.size(4);

    int OD = D / 4;
    int OH = H / 4;
    int OW = W / 4;

    auto y = torch::empty({B, C, OD, OH, OW}, x.options());

    int out_numel = B * C * OD * OH * OW;
    const int threads = 256;
    int blocks = (out_numel + threads - 1) / threads;

    hipLaunchKernelGGL(softmax_pool4_kernel, dim3(blocks), dim3(threads), 0, 0,
                      (const float*)x.data_ptr<float>(), (float*)y.data_ptr<float>(),
                      B, C, D, H, W, OD, OH, OW);
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_pool4_hip", &softmax_pool4_hip, "Fused softmax+maxpoolx2 (HIP)");
}
'''

softmax_pool4_ext = load_inline(
