import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Use hipcc for ROCm builds
os.environ.setdefault("CXX", "hipcc")

# Fused row-wise softmax for FP32, optimized for (B, N) where N is large (e.g., 16384)
# One block per row.
softmax_cpp = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

#ifndef __HIP_PLATFORM_HCC__
#define __HIP_PLATFORM_HCC__ 1
#endif

static inline __device__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

static inline __device__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void softmax_row_fp32_kernel(const float* __restrict__ x,
                                       float* __restrict__ y,
                                       int64_t rows,
                                       int64_t cols) {
    int row = (int)blockIdx.x;
    if (row >= rows) return;

    // Each block handles one row.
    // Thread layout: 256 threads.
    int tid = (int)threadIdx.x;

    // Step 1: compute row max
    float local_max = -INFINITY;
    int64_t base = (int64_t)row * cols;

    // Stride over columns
    for (int64_t c = tid; c < cols; c += blockDim.x) {
        float v = x[base + c];
        local_max = fmaxf(local_max, v);
    }

    // Reduce within block: first warp reduce, then shared across warps.
    local_max = warp_reduce_max(local_max);

    __shared__ float s_max[8]; // 256 threads -> 8 warps
    int lane = tid & 31;
    int warp = tid >> 5;
    if (lane == 0) s_max[warp] = local_max;
    __syncthreads();

    float row_max = -INFINITY;
    if (warp == 0) {
        float v = (lane < 8) ? s_max[lane] : -INFINITY;
        v = warp_reduce_max(v);
        if (lane == 0) s_max[0] = v;
    }
    __syncthreads();
    row_max = s_max[0];

    // Step 2: compute sum(exp(x - max))
    float local_sum = 0.0f;
    for (int64_t c = tid; c < cols; c += blockDim.x) {
        float v = x[base + c] - row_max;
        local_sum += __expf(v);
    }

    local_sum = warp_reduce_sum(local_sum);

    __shared__ float s_sum[8];
    if (lane == 0) s_sum[warp] = local_sum;
    __syncthreads();

    float row_sum = 0.0f;
    if (warp == 0) {
        float v = (lane < 8) ? s_sum[lane] : 0.0f;
        v = warp_reduce_sum(v);
        if (lane == 0) s_sum[0] = v;
    }
    __syncthreads();
    row_sum = s_sum[0];

    // Step 3: write outputs
    float inv = 1.0f / row_sum;
    for (int64_t c = tid; c < cols; c += blockDim.x) {
        float v = x[base + c] - row_max;
        y[base + c] = __expf(v) * inv;
    }
}

torch::Tensor softmax_row_fp32(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D (B, N)");
    auto x_contig = x.contiguous();
    const auto rows = x_contig.size(0);
    const auto cols = x_contig.size(1);

    auto y = torch::empty_like(x_contig);

    const int threads = 256;
    const dim3 blocks((unsigned int)rows);

    hipLaunchKernelGGL(softmax_row_fp32_kernel,
                      blocks,
                      dim3(threads),
                      0,
                      at::hip::getDefaultHIPStream(),
                      (const float*)x_contig.data_ptr<float>(),
                      (float*)y.data_ptr<float>(),
                      (int64_t)rows,
                      (int64_t)cols);

    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_row_fp32", &softmax_row_fp32, "Row-wise softmax FP32 (ROCm)");
}
"""

softmax_ext = load_inline(
    name="softmax_row_fp32_ext",
    cpp_sources=softmax_cpp,
    functions=None,
    extra_cuda_cflags=["-O3"],
    with_cuda=True,
    verbose=False,
)


class ModelNew(nn.Module):
    """Optimized: keep GEMM via rocBLAS, replace softmax with custom HIP kernel in eval mode."""

    def __init__(self, in_features, out_features, dropout_p):
        super().__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.dropout = nn.Dropout(dropout_p)

    def forward(self, x):
        x = self.matmul(x)
        if self.training:
            # Preserve exact dropout semantics during training
            x = self.dropout(x)
            x = torch.softmax(x, dim=1)
            return x
        # In eval: dropout is identity; fuse by skipping dropout and using custom softmax
        return softmax_ext.softmax_row_fp32(x)


