# Optimization strategy:
# 1) Algebraic simplification removes clone+detach and residual add:
#       out = x*scaling_factor + x = x*(1+scaling_factor)
# 2) Apply scaling IN-PLACE on the Linear output to avoid an extra allocation.

scale_cpp = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>

template <int VEC>
__global__ void scale_inplace_kernel(float* __restrict__ x, float factor, int n) {
    int tid = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int idx = tid * VEC;
    if (idx >= n) return;

    #pragma unroll
    for (int i = 0; i < VEC; i++) {
        int j = idx + i;
        if (j < n) x[j] *= factor;
    }
}

void scale_inplace_fp32(torch::Tensor x, double factor_d) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    const int n = (int)x.numel();
    const float factor = (float)factor_d;

    uintptr_t addr = (uintptr_t)x.data_ptr<float>();
    bool aligned16 = (addr & 0xF) == 0;

    const int threads = 256;
    if (aligned16) {
        const int VEC = 4;
        int blocks = (n + (threads * VEC - 1)) / (threads * VEC);
        hipLaunchKernelGGL((scale_inplace_kernel<VEC>), dim3(blocks), dim3(threads), 0, 0,
                           (float*)x.data_ptr<float>(), factor, n);
    } else {
        const int VEC = 1;
        int blocks = (n + (threads * VEC - 1)) / (threads * VEC);
        hipLaunchKernelGGL((scale_inplace_kernel<VEC>), dim3(blocks), dim3(threads), 0, 0,
                           (float*)x.data_ptr<float>(), factor, n);
    }
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("scale_inplace_fp32", &scale_inplace_fp32, "In-place scale fp32 tensor (HIP)");
}
"""

