#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__device__ __forceinline__ float gelu_erf(float x) {
    const float inv_sqrt2 = 0.7071067811865475244f;
    return 0.5f * x * (1.0f + erff(x * inv_sqrt2));
}

__global__ void div_gelu_inplace_kernel(float* __restrict__ x, int64_t n, float inv_div) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)blockDim.x * gridDim.x;

    int64_t n4 = n / 4;
    float4* x4 = reinterpret_cast<float4*>(x);
    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = x4[i];
        float a = v.x * inv_div;
        float b = v.y * inv_div;
        float c = v.z * inv_div;
        float d = v.w * inv_div;
        v.x = gelu_erf(a);
        v.y = gelu_erf(b);
        v.z = gelu_erf(c);
        v.w = gelu_erf(d);
        x4[i] = v;
    }

    int64_t base = n4 * 4;
    for (int64_t j = base + idx; j < n; j += stride) {
        float a = x[j] * inv_div;
        x[j] = gelu_erf(a);
    }
}

