    if (blocks > 4096) blocks = 4096;

    hipStream_t stream = (hipStream_t)at::cuda::getDefaultCUDAStream();
    hipLaunchKernelGGL(div_gelu_inplace_kernel, dim3(blocks), dim3(threads), 0, stream,
                       (float*)x.data_ptr<float>(), n, inv_div);
    return x;
}

