#include <torch/extension.h>
#include <hip/hip_runtime.h>

// Vectorized over 4 contiguous FP32 values when possible.
__global__ void bn_scale_nchw_f32x4_kernel(
    const float* __restrict__ x,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    int N, int C, int H, int W,
    float eps,
    float scale)
{
    int tid = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int total = N * C * H * W;

    int i = tid * 4;
    int stride = blockDim.x * gridDim.x * 4;

    for (; i + 3 < total; i += stride) {
        // process 4 scalars; handle possible channel boundary crossing.
        #pragma unroll
        for (int lane = 0; lane < 4; lane++) {
            int idx = i + lane;
            int t = idx / W;
            t /= H;
            int c = t % C;

            float xm = x[idx];
            float inv_std = rsqrtf(var[c] + eps);
            float out = (xm - mean[c]) * inv_std;
            out = out * weight[c] + bias[c];
            y[idx] = out * scale;
        }
    }

    // tail
    for (; i < total; i += stride) {
        int idx = i;
        int t = idx / W;
        t /= H;
        int c = t % C;

        float xm = x[idx];
        float inv_std = rsqrtf(var[c] + eps);
        float out = (xm - mean[c]) * inv_std;
        out = out * weight[c] + bias[c];
        y[idx] = out * scale;
    }
}

