softmax_cpp = r"""
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

static inline __device__ float warp_reduce_max(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val = fmaxf(val, __shfl_down(val, offset));
    }
    return val;
}

static inline __device__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down(val, offset);
    }
    return val;
}

__global__ void softmax_row_fp32_kernel(const float* __restrict__ x,
                                       float* __restrict__ y,
                                       int64_t rows,
                                       int64_t cols) {
    int row = (int)blockIdx.x;
    if (row >= rows) return;

    int tid = (int)threadIdx.x;
    int64_t base = (int64_t)row * cols;

    float local_max = -INFINITY;
    for (int64_t c = tid; c < cols; c += (int)blockDim.x) {
        float v = x[base + c];
        local_max = fmaxf(local_max, v);
    }

    local_max = warp_reduce_max(local_max);

    __shared__ float s_max[8];
    int lane = tid & 31;
    int warp = tid >> 5;
    if (lane == 0) s_max[warp] = local_max;
    __syncthreads();

    if (warp == 0) {
        float v = (lane < 8) ? s_max[lane] : -INFINITY;
        v = warp_reduce_max(v);
        if (lane == 0) s_max[0] = v;
    }
    __syncthreads();
    float row_max = s_max[0];

    float local_sum = 0.0f;
    for (int64_t c = tid; c < cols; c += (int)blockDim.x) {
        float v = x[base + c] - row_max;
        local_sum += __expf(v);
    }

    local_sum = warp_reduce_sum(local_sum);

    __shared__ float s_sum[8];
    if (lane == 0) s_sum[warp] = local_sum;
    __syncthreads();

    if (warp == 0) {
        float v = (lane < 8) ? s_sum[lane] : 0.0f;
        v = warp_reduce_sum(v);
        if (lane == 0) s_sum[0] = v;
    }
    __syncthreads();
    float row_sum = s_sum[0];

    float inv = 1.0f / row_sum;
    for (int64_t c = tid; c < cols; c += (int)blockDim.x) {
        float v = x[base + c] - row_max;
        y[base + c] = __expf(v) * inv;
    }
}

torch::Tensor softmax_row_fp32(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA/ROCm tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D (B, N)");

    auto x_contig = x.contiguous();
    const auto rows = x_contig.size(0);
    const auto cols = x_contig.size(1);

    auto y = torch::empty_like(x_contig);

    const int threads = 256;
    dim3 blocks((unsigned int)rows);

    // On ROCm builds, CUDA stream is backed by hipStream_t.
    hipStream_t stream = (hipStream_t)at::cuda::getDefaultCUDAStream();

    hipLaunchKernelGGL(softmax_row_fp32_kernel,
                      blocks,
                      dim3(threads),
                      0,
                      stream,
                      (const float*)x_contig.data_ptr<float>(),
                      (float*)y.data_ptr<float>(),
                      (int64_t)rows,
                      (int64_t)cols);

    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("softmax_row_fp32", &softmax_row_fp32, "Row-wise softmax FP32 (ROCm)");
}
"""

