#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__device__ __forceinline__ float fast_tanh(float x) {
    // Clang builtin maps to device implementation under HIP
    return __builtin_tanhf(x);
}

template<int POOL_K>
__global__ void fused_tanh_scale_bias_maxpool_kernel(
    const float* __restrict__ x,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int N, int C, int H, int W,
    float scale,
    int OH, int OW)
{
    int idx = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int total = N * C * OH * OW;
    if (idx >= total) return;

    int ow = idx % OW;
    int t = idx / OW;
    int oh = t % OH;
    t /= OH;
    int c = t % C;
    int n = t / C;

    int base_h = oh * POOL_K;
    int base_w = ow * POOL_K;

    const int HW = H * W;
    const float* x_nc = x + (n * C + c) * HW;

    float b = bias[c];
    float m = -INFINITY;

    #pragma unroll
    for (int ph = 0; ph < POOL_K; ++ph) {
        int ih = base_h + ph;
        const float* row = x_nc + ih * W + base_w;
        #pragma unroll
        for (int pw = 0; pw < POOL_K; ++pw) {
            float v = row[pw];
            v = fast_tanh(v);
            v = v * scale + b;
            m = v > m ? v : m;
        }
    }

    out[idx] = m;
}

