# Fused GELU(approx) + Softmax for FP32, specialized for 2D [B, N] with softmax over N.
# Uses one block per row; vectorized float4 IO; computes GELU once into output buffer, then softmax in-place.

source = r'''
#include <torch/extension.h>
#include <hip/hip_runtime.h>

__device__ __forceinline__ float gelu_fast(float x) {
    // Fast GELU approximation: x * sigmoid(1.702 * x)
    // Common in inference, significantly cheaper than tanh-based exact-ish GELU.
    float z = 1.702f * x;
    float s = 1.0f / (1.0f + __expf(-z));
    return x * s;
}

template<int THREADS>
__global__ void gelu_softmax_row_kernel_vec4(const float* __restrict__ inp, float* __restrict__ out, int cols) {
    int row = (int)blockIdx.x;
    int tid = (int)threadIdx.x;
    int base = row * cols;

    // cols is expected multiple of 4 for vectorization
    int cols4 = cols >> 2;
    const float4* __restrict__ in4 = reinterpret_cast<const float4*>(inp + base);
    float4* __restrict__ out4 = reinterpret_cast<float4*>(out + base);

    // Pass 0: compute GELU once and store to out (temporary)
    for (int c4 = tid; c4 < cols4; c4 += THREADS) {
        float4 v = in4[c4];
        v.x = gelu_fast(v.x);
        v.y = gelu_fast(v.y);
        v.z = gelu_fast(v.z);
        v.w = gelu_fast(v.w);
        out4[c4] = v;
    }
    __syncthreads();

    // Pass 1: max reduction over out
    float local_max = -INFINITY;
    const float* __restrict__ outp = out + base;
    for (int c = tid; c < cols; c += THREADS) {
        local_max = fmaxf(local_max, outp[c]);
    }

    __shared__ float smax[THREADS];
    smax[tid] = local_max;
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) smax[tid] = fmaxf(smax[tid], smax[tid + offset]);
        __syncthreads();
    }
    float row_max = smax[0];

    // Pass 2: sum exp(out - max)
    float local_sum = 0.0f;
    for (int c = tid; c < cols; c += THREADS) {
        local_sum += __expf(outp[c] - row_max);
    }

    __shared__ float ssum[THREADS];
    ssum[tid] = local_sum;
    __syncthreads();
    for (int offset = THREADS / 2; offset > 0; offset >>= 1) {
        if (tid < offset) ssum[tid] += ssum[tid + offset];
        __syncthreads();
    }
    float inv_denom = 1.0f / ssum[0];

    // Pass 3: write normalized exp(out-max)
    for (int c4 = tid; c4 < cols4; c4 += THREADS) {
        float4 v = out4[c4];
        v.x = __expf(v.x - row_max) * inv_denom;
        v.y = __expf(v.y - row_max) * inv_denom;
        v.z = __expf(v.z - row_max) * inv_denom;
        v.w = __expf(v.w - row_max) * inv_denom;
        out4[c4] = v;
    }
}

torch::Tensor gelu_softmax_hip(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA/HIP tensor");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(x.dim() == 2, "x must be 2D [B, N]");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
    TORCH_CHECK((x.size(1) % 4) == 0, "N must be multiple of 4 for vec4 kernel");

    int B = (int)x.size(0);
    int N = (int)x.size(1);
    auto out = torch::empty_like(x);

    constexpr int THREADS = 256;
    dim3 block(THREADS);
    dim3 grid(B);
    hipLaunchKernelGGL((gelu_softmax_row_kernel_vec4<THREADS>), grid, block, 0, 0,
                      (const float*)x.data_ptr<float>(), (float*)out.data_ptr<float>(), N);
    return out;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_softmax_hip", &gelu_softmax_hip, "Fused GELU(approx) + Softmax (HIP)");
}
'''

_gelu_softmax_ext = load_inline(
    name='gelu_softmax_ext_v2',
